#pragma once
#include <filesystem>
#include <fstream>
inline void WriteCanonicalGarmentInput(const std::filesystem::path& path,const G::Input& input){
 std::ofstream f(path);f.precision(17);auto point=[&](G::Point p){f<<'['<<p[0]<<','<<p[1]<<','<<p[2]<<']';};auto samples=[&](const auto& rows){f<<'[';bool first=true;for(const auto& s:rows){if(!first)f<<',';first=false;f<<"{\"position\":";point(s.position);f<<",\"normal\":";point(s.normal);f<<",\"lineage\":[";for(unsigned i=0;i<s.lineage.donors.size();i++){if(i)f<<',';const auto& d=s.lineage.donors[i];f<<"{\"surface\":"<<unsigned(d.surface)<<",\"vertex\":"<<d.vertex<<",\"weight\":"<<d.weight<<'}';}f<<"]}";}f<<']';};auto faces=[&](const auto& triangles){f<<'[';bool first=true;for(auto t:triangles){if(!first)f<<',';first=false;f<<'['<<t[0]<<','<<t[1]<<','<<t[2]<<']';}f<<']';};
 f<<"{\"schema\":\"malemod-garment-input-json-1\",\"source\":\"Completed canonical native source buffers at identity authoring pose; not gameplay\",\"donorCapacity\":16,\"frame\":{\"origin\":";point(input.frame.origin);f<<",\"lateral\":";point(input.frame.lateral);f<<",\"forward\":";point(input.frame.forward);f<<",\"up\":";point(input.frame.up);f<<"},\"characterEpoch\":"<<input.characterEpoch<<",\"topologyRevision\":"<<input.topologyRevision<<",\"restRevision\":"<<input.restRevision<<",\"deltaTime\":"<<input.deltaTime<<",\"anatomyMass\":"<<input.anatomyMass<<",\"gravity\":";point(input.gravity);
 f<<",\"waist\":";samples(input.waist);f<<",\"opening\":";samples(input.opening);f<<",\"anatomy\":";samples(input.anatomy);f<<",\"rearStraps\":[";samples(input.rearStraps[0]);f<<',';samples(input.rearStraps[1]);f<<"],\"anatomyTriangles\":";faces(input.anatomyTriangles);f<<",\"bodySurface\":";samples(input.bodySurface);f<<",\"bodyTriangles\":";faces(input.bodyTriangles);f<<",\"bodyContacts\":[],\"anatomyRegions\":[";for(unsigned k=0;k<4;k++){if(k)f<<',';f<<'[';for(unsigned i=0;i<input.anatomyRegions[k].size();i++){if(i)f<<',';f<<input.anatomyRegions[k][i];}f<<']';}f<<"]}\n";if(!f)throw std::runtime_error("Typed canonical input JSON write failed");
}
